def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_coop_rate = opp_c / n

    recent = history[-5:] if n >= 5 else history
    recent_opp_c = 0
    for _, o in recent:
        if o == 'C':
            recent_opp_c += 1

    if n >= 5 and recent_opp_c == 0:
        return 'D'

    if opp_last == 'D':
        if my_last == 'C':
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'
        else:
            mutual_def_streak = 0
            for m, o in reversed(history):
                if m == 'D' and o == 'D':
                    mutual_def_streak += 1
                else:
                    break
            if mutual_def_streak >= 2 and opp_coop_rate > 0.5 and recent_opp_c >= 2:
                return 'C'
            return 'D'
    else:
        return 'C'
